def tiene_veredicto(ruta):
    """Devuelve True solo si el documento en 'ruta' trae veredicto del equipo.

    Un documento trae veredicto cuando en su texto aparecen las dos palabras
    APROBADO y EQUIPO, sin distinguir mayusculas de minusculas. Si falta una de
    las dos, no trae veredicto. Nunca revienta: ante cualquier duda (ruta vacia,
    None, no existe, es carpeta, no se puede leer) devuelve False.
    """
    if not ruta:
        return False
    try:
        with open(ruta, "r", encoding="utf-8", errors="replace") as f:
            texto = f.read()
    except Exception:
        return False
    texto = texto.upper()
    return ("APROBADO" in texto) and ("EQUIPO" in texto)

